/* =====================================================================================================================
 * Small linear algebra (3x3 row-major) and rotations
 * ===================================================================================================================== */

static const double I3[9] = {1, 0, 0, 0, 1, 0, 0, 0, 1};

static void m3mul(const double *a, const double *b, double *c) { /* c = a b */
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) c[3 * i + j] = a[3 * i] * b[j] + a[3 * i + 1] * b[3 + j] + a[3 * i + 2] * b[6 + j];
}
static void m3tmul(const double *a, const double *b, double *c) { /* c = a^T b */
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) c[3 * i + j] = a[i] * b[j] + a[3 + i] * b[3 + j] + a[6 + i] * b[6 + j];
}
static void m3vec(const double *a, const double *x, double *y) { /* y = a x */
    for (int i = 0; i < 3; i++) y[i] = a[3 * i] * x[0] + a[3 * i + 1] * x[1] + a[3 * i + 2] * x[2];
}
static void m3tvec(const double *a, const double *x, double *y) { /* y = a^T x */
    for (int i = 0; i < 3; i++) y[i] = a[i] * x[0] + a[3 + i] * x[1] + a[6 + i] * x[2];
}
static void skew(const double *w, double *k) { /* [w]x */
    k[0] = 0; k[1] = -w[2]; k[2] = w[1]; k[3] = w[2]; k[4] = 0; k[5] = -w[0]; k[6] = -w[1]; k[7] = w[0]; k[8] = 0;
}
static void exp_so3(const double *w, double *r) { /* Rodrigues */
    double angle = sqrt(w[0] * w[0] + w[1] * w[1] + w[2] * w[2]), k[9], kk[9];
    if (angle < 1e-12) {
        skew(w, k);
        for (int i = 0; i < 9; i++) r[i] = k[i] + (i % 4 == 0);
        return;
    }
    double u[3] = {w[0] / angle, w[1] / angle, w[2] / angle};
    skew(u, k);
    m3mul(k, k, kk);
    double s = sin(angle), c = 1 - cos(angle);
    for (int i = 0; i < 9; i++) r[i] = (i % 4 == 0) + s * k[i] + c * kk[i];
}
static void rot_right(double *Rm, const double *w) { /* Rm <- Rm Exp(w) */
    double e[9], t[9];
    exp_so3(w, e);
    m3mul(Rm, e, t);
    memcpy(Rm, t, sizeof t);
}
static void align_to_z(const double *f_in, double *r) { /* minimal rotation with r f_hat = +z (keeps yaw) */
    double n = sqrt(f_in[0] * f_in[0] + f_in[1] * f_in[1] + f_in[2] * f_in[2]);
    double f[3] = {f_in[0] / n, f_in[1] / n, f_in[2] / n}, axis[3] = {f[1], -f[0], 0.0};
    double s = sqrt(axis[0] * axis[0] + axis[1] * axis[1]), c = f[2];
    if (s < 1e-9) {
        memset(r, 0, 9 * sizeof(double));
        r[0] = 1; r[4] = c > 0 ? 1 : -1; r[8] = c > 0 ? 1 : -1;
        return;
    }
    double a = atan2(s, c), w[3] = {axis[0] / s * a, axis[1] / s * a, 0.0};
    exp_so3(w, r);
}
static void matrix_to_quaternion(const double *m, double *q) { /* q = [x, y, z, w], unit */
    double tr = m[0] + m[4] + m[8];
    if (tr > 0) {
        double s = sqrt(tr + 1.0) * 2;
        q[0] = (m[7] - m[5]) / s; q[1] = (m[2] - m[6]) / s; q[2] = (m[3] - m[1]) / s; q[3] = 0.25 * s;
    } else {
        int i = 0;
        if (m[4] > m[0]) i = 1;
        if (m[8] > m[3 * i + i]) i = 2;
        int j = (i + 1) % 3, k = (i + 2) % 3;
        double s = sqrt(1.0 + m[3 * i + i] - m[3 * j + j] - m[3 * k + k]) * 2;
        q[i] = 0.25 * s;
        q[j] = (m[3 * j + i] + m[3 * i + j]) / s;
        q[k] = (m[3 * k + i] + m[3 * i + k]) / s;
        q[3] = (m[3 * k + j] - m[3 * j + k]) / s;
    }
    double n = sqrt(q[0] * q[0] + q[1] * q[1] + q[2] * q[2] + q[3] * q[3]);
    for (int i = 0; i < 4; i++) q[i] /= n;
}
static int solve3(const double *A, const double *b, double *x) { /* x = A^-1 b by the adjugate */
    double det = A[0] * (A[4] * A[8] - A[5] * A[7]) - A[1] * (A[3] * A[8] - A[5] * A[6]) + A[2] * (A[3] * A[7] - A[4] * A[6]);
    if (fabs(det) < 1e-300) return 0;
    double inv[9] = {(A[4] * A[8] - A[5] * A[7]) / det, (A[2] * A[7] - A[1] * A[8]) / det, (A[1] * A[5] - A[2] * A[4]) / det,
                     (A[5] * A[6] - A[3] * A[8]) / det, (A[0] * A[8] - A[2] * A[6]) / det, (A[2] * A[3] - A[0] * A[5]) / det,
                     (A[3] * A[7] - A[4] * A[6]) / det, (A[1] * A[6] - A[0] * A[7]) / det, (A[0] * A[4] - A[1] * A[3]) / det};
    m3vec(inv, b, x);
    return 1;
}
static void sym3_eig_minmax(const double *A, double *lmin, double *lmax) { /* closed form, symmetric 3x3 */
    double p1 = A[1] * A[1] + A[2] * A[2] + A[5] * A[5];
    double q = (A[0] + A[4] + A[8]) / 3;
    if (p1 < 1e-300) {
        double a = A[0], b = A[4], c = A[8];
        *lmin = fmin(a, fmin(b, c)); *lmax = fmax(a, fmax(b, c));
        return;
    }
    double p2 = (A[0] - q) * (A[0] - q) + (A[4] - q) * (A[4] - q) + (A[8] - q) * (A[8] - q) + 2 * p1;
    double p = sqrt(p2 / 6), B[9];
    for (int i = 0; i < 9; i++) B[i] = (A[i] - (i % 4 == 0 ? q : 0)) / p;
    double r = (B[0] * (B[4] * B[8] - B[5] * B[7]) - B[1] * (B[3] * B[8] - B[5] * B[6]) + B[2] * (B[3] * B[7] - B[4] * B[6])) / 2;
    double phi = r <= -1 ? M_PI / 3 : r >= 1 ? 0 : acos(r) / 3;
    *lmax = q + 2 * p * cos(phi);
    *lmin = q + 2 * p * cos(phi + 2 * M_PI / 3);
}

/* =====================================================================================================================
 * Generic EKF update
 * ===================================================================================================================== */

#define MAXK MAXD
static double HP[MAXK * MAXD], Kt[MAXK * MAXD], Sm[MAXK * MAXK];

static int cholesky(double *A, int n) { /* in place, lower triangle; 0 if not positive definite */
    for (int j = 0; j < n; j++) {
        double s = A[j * n + j];
        for (int k = 0; k < j; k++) s -= A[j * n + k] * A[j * n + k];
        if (s <= 1e-300) return 0;
        s = sqrt(s);
        A[j * n + j] = s;
        for (int i = j + 1; i < n; i++) {
            double t = A[i * n + j];
            for (int k = 0; k < j; k++) t -= A[i * n + k] * A[j * n + k];
            A[i * n + j] = t / s;
        }
    }
    return 1;
}
static void chol_solve(const double *L, int n, double *b) { /* L L^T x = b, in place */
    for (int i = 0; i < n; i++) {
        double s = b[i];
        for (int k = 0; k < i; k++) s -= L[i * n + k] * b[k];
        b[i] = s / L[i * n + i];
    }
    for (int i = n - 1; i >= 0; i--) {
        double s = b[i];
        for (int k = i + 1; k < n; k++) s -= L[k * n + i] * b[k];
        b[i] = s / L[i * n + i];
    }
}

/* apply an error-state correction to the nominal state (orientation errors on the right) */
static void inject(const double *dx) {
    rot_right(R, dx + TH);
    for (int i = 0; i < 3; i++) { vel[i] += dx[V + i]; pos[i] += dx[P + i]; bg[i] += dx[BG + i]; ba[i] += dx[BA + i]; }
    rot_right(R0, dx + TH0);
    for (int c = 0; c < nclones; c++) {
        int o = CORE + 6 * c;
        rot_right(clones[c].R, dx + o);
        for (int i = 0; i < 3; i++) clones[c].p[i] += dx[o + 3 + i];
    }
}

/* EKF update with residual r (k), Jacobian H (k x D, row-major, leading dimension MAXD) and isotropic noise variance.
 * Rejected (returns 0) if r^T S^-1 r > gate. Sums run only over the columns where H is nonzero.
 * P <- P - (HP)^T S^-1 HP, written symmetrically. */
static int update(const double *r, const double *H, int k, double noise, double gate) {
    int nz[MAXD], nnz = 0;
    for (int i = 0; i < D; i++) {
        int any = 0;
        for (int a = 0; a < k && !any; a++) any = H[a * MAXD + i] != 0;
        if (any) nz[nnz++] = i;
    }
#if F_UPD
    { /* HP = H P: two rows of H at a time, six columns (three f64x2) per chunk, accumulators in registers (same per-element order) */
        const double *prow[MAXD];
        for (int q = 0; q < nnz; q++) prow[q] = Pm + nz[q] * MAXD;
        for (int a = 0; a < k; a += 2) {
            const double *h0 = H + a * MAXD, *h1 = H + (a + 1 < k ? a + 1 : a) * MAXD;
            double *o0 = HP + a * MAXD, *o1 = HP + (a + 1 < k ? a + 1 : a) * MAXD;
            for (int j = 0; j < D; j += 6) {
                v128_t a00 = wasm_f64x2_splat(0), a01 = a00, a02 = a00, a10 = a00, a11 = a00, a12 = a00;
                for (int q = 0; q < nnz; q++) {
                    const v128_t c0 = wasm_f64x2_splat(h0[nz[q]]), c1 = wasm_f64x2_splat(h1[nz[q]]);
                    const double *pr = prow[q] + j;
                    const v128_t p0 = wasm_v128_load(pr), p1 = wasm_v128_load(pr + 2), p2 = wasm_v128_load(pr + 4);
                    a00 = wasm_f64x2_add(a00, wasm_f64x2_mul(c0, p0)); a01 = wasm_f64x2_add(a01, wasm_f64x2_mul(c0, p1)); a02 = wasm_f64x2_add(a02, wasm_f64x2_mul(c0, p2));
                    a10 = wasm_f64x2_add(a10, wasm_f64x2_mul(c1, p0)); a11 = wasm_f64x2_add(a11, wasm_f64x2_mul(c1, p1)); a12 = wasm_f64x2_add(a12, wasm_f64x2_mul(c1, p2));
                }
                wasm_v128_store(o0 + j, a00); wasm_v128_store(o0 + j + 2, a01); wasm_v128_store(o0 + j + 4, a02);
                wasm_v128_store(o1 + j, a10); wasm_v128_store(o1 + j + 2, a11); wasm_v128_store(o1 + j + 4, a12);
            }
        }
    }
#else
    for (int a = 0; a < k; a++) /* HP = H P */
        for (int j = 0; j < D; j++) {
            double s = 0;
            const double *h = H + a * MAXD;
            for (int q = 0; q < nnz; q++) s += h[nz[q]] * Pm[nz[q] * MAXD + j];
            HP[a * MAXD + j] = s;
        }
#endif
#if F_UPD
    {
        static double HT[MAXD * (MAXK + 2)];
        const int ld = k + (k & 1);
        for (int q = 0; q < nnz; q++) {
            for (int b2 = 0; b2 < k; b2++) HT[q * ld + b2] = H[b2 * MAXD + nz[q]];
            if (k & 1) HT[q * ld + k] = 0;
        }
        for (int a = 0; a < k; a++) {
            double hpc[MAXD];
            for (int q = 0; q < nnz; q++) hpc[q] = HP[a * MAXD + nz[q]];
            const int nv = (a + 2) / 2;
            double tmp[MAXK + 4];
            int bv = 0;
            for (; bv + 2 <= nv; bv += 2) {
                v128_t s0 = wasm_f64x2_splat(0), s1 = s0;
                for (int q = 0; q < nnz; q++) {
                    const v128_t c = wasm_f64x2_splat(hpc[q]);
                    const double *ht = HT + q * ld + 2 * bv;
                    s0 = wasm_f64x2_add(s0, wasm_f64x2_mul(c, wasm_v128_load(ht))); s1 = wasm_f64x2_add(s1, wasm_f64x2_mul(c, wasm_v128_load(ht + 2)));
                }
                wasm_v128_store(tmp + 2 * bv, s0); wasm_v128_store(tmp + 2 * bv + 2, s1);
            }
            if (bv < nv) {
                v128_t s0 = wasm_f64x2_splat(0);
                for (int q = 0; q < nnz; q++) s0 = wasm_f64x2_add(s0, wasm_f64x2_mul(wasm_f64x2_splat(hpc[q]), wasm_v128_load(HT + q * ld + 2 * bv)));
                wasm_v128_store(tmp + 2 * bv, s0);
            }
            for (int b2 = 0; b2 <= a; b2++) Sm[a * k + b2] = Sm[b2 * k + a] = tmp[b2] + (a == b2 ? noise : 0);
        }
    }
#else
    for (int a = 0; a < k; a++) /* S = H P H^T + noise I */
        for (int b = 0; b <= a; b++) {
            double s = 0;
            for (int q = 0; q < nnz; q++) s += HP[a * MAXD + nz[q]] * H[b * MAXD + nz[q]];
            Sm[a * k + b] = Sm[b * k + a] = s + (a == b ? noise : 0);
        }
#endif
    if (!cholesky(Sm, k)) return 0;
    double y[MAXK];
    memcpy(y, r, k * sizeof(double));
    chol_solve(Sm, k, y); /* y = S^-1 r */
    double m2 = 0;
    for (int a = 0; a < k; a++) m2 += r[a] * y[a];
    if (m2 > gate) return 0;
#if F_UPD
    { /* Kt = S^-1 HP by forward then backward substitution on rows, six columns per chunk in registers (per-column arithmetic unchanged) */
        for (int i = 0; i < k; i++) {
            const double d = Sm[i * k + i];
            const v128_t dd = wasm_f64x2_splat(d);
            for (int j = 0; j < D; j += 6) {
                v128_t s0 = wasm_v128_load(HP + i * MAXD + j), s1 = wasm_v128_load(HP + i * MAXD + j + 2), s2 = wasm_v128_load(HP + i * MAXD + j + 4);
                for (int kk = 0; kk < i; kk++) {
                    const v128_t c = wasm_f64x2_splat(Sm[i * k + kk]);
                    const double *bk = Kt + kk * MAXD + j;
                    s0 = wasm_f64x2_sub(s0, wasm_f64x2_mul(c, wasm_v128_load(bk))); s1 = wasm_f64x2_sub(s1, wasm_f64x2_mul(c, wasm_v128_load(bk + 2)));
                    s2 = wasm_f64x2_sub(s2, wasm_f64x2_mul(c, wasm_v128_load(bk + 4)));
                }
                wasm_v128_store(Kt + i * MAXD + j, wasm_f64x2_div(s0, dd)); wasm_v128_store(Kt + i * MAXD + j + 2, wasm_f64x2_div(s1, dd));
                wasm_v128_store(Kt + i * MAXD + j + 4, wasm_f64x2_div(s2, dd));
            }
        }
        for (int i = k - 1; i >= 0; i--) {
            const double d = Sm[i * k + i];
            const v128_t dd = wasm_f64x2_splat(d);
            for (int j = 0; j < D; j += 6) {
                v128_t s0 = wasm_v128_load(Kt + i * MAXD + j), s1 = wasm_v128_load(Kt + i * MAXD + j + 2), s2 = wasm_v128_load(Kt + i * MAXD + j + 4);
                for (int kk = i + 1; kk < k; kk++) {
                    const v128_t c = wasm_f64x2_splat(Sm[kk * k + i]);
                    const double *bk = Kt + kk * MAXD + j;
                    s0 = wasm_f64x2_sub(s0, wasm_f64x2_mul(c, wasm_v128_load(bk))); s1 = wasm_f64x2_sub(s1, wasm_f64x2_mul(c, wasm_v128_load(bk + 2)));
                    s2 = wasm_f64x2_sub(s2, wasm_f64x2_mul(c, wasm_v128_load(bk + 4)));
                }
                wasm_v128_store(Kt + i * MAXD + j, wasm_f64x2_div(s0, dd)); wasm_v128_store(Kt + i * MAXD + j + 2, wasm_f64x2_div(s1, dd));
                wasm_v128_store(Kt + i * MAXD + j + 4, wasm_f64x2_div(s2, dd));
            }
        }
    }
    double dx[MAXD];
    for (int j = 0; j < D; j += 6) {
        v128_t s0 = wasm_f64x2_splat(0), s1 = s0, s2 = s0;
        for (int a = 0; a < k; a++) {
            const v128_t c = wasm_f64x2_splat(r[a]);
            const double *kt = Kt + a * MAXD + j;
            s0 = wasm_f64x2_add(s0, wasm_f64x2_mul(wasm_v128_load(kt), c)); s1 = wasm_f64x2_add(s1, wasm_f64x2_mul(wasm_v128_load(kt + 2), c));
            s2 = wasm_f64x2_add(s2, wasm_f64x2_mul(wasm_v128_load(kt + 4), c));
        }
        wasm_v128_store(dx + j, s0); wasm_v128_store(dx + j + 2, s1); wasm_v128_store(dx + j + 4, s2);
    }
    {
#if F_UPD2
        static double srow[4][MAXD + 6];
        for (int i0 = 0; i0 < D; i0 += 4) {
            const int r1 = i0 + 1 < D ? i0 + 1 : D - 1, r2 = i0 + 2 < D ? i0 + 2 : D - 1, r3 = i0 + 3 < D ? i0 + 3 : D - 1;
            const int j0 = i0 - i0 % 6;
            for (int j = j0; j < D; j += 6) {
                v128_t s00 = wasm_f64x2_splat(0), s01 = s00, s02 = s00, s10 = s00, s11 = s00, s12 = s00, s20 = s00, s21 = s00, s22 = s00, s30 = s00, s31 = s00, s32 = s00;
                for (int a = 0; a < k; a++) {
                    const double *kt = Kt + a * MAXD + j, *hpa = HP + a * MAXD;
                    const v128_t k0v = wasm_v128_load(kt), k1v = wasm_v128_load(kt + 2), k2v = wasm_v128_load(kt + 4);
                    const v128_t c0 = wasm_f64x2_splat(hpa[i0]), c1 = wasm_f64x2_splat(hpa[r1]), c2 = wasm_f64x2_splat(hpa[r2]), c3 = wasm_f64x2_splat(hpa[r3]);
                    s00 = wasm_f64x2_add(s00, wasm_f64x2_mul(c0, k0v)); s01 = wasm_f64x2_add(s01, wasm_f64x2_mul(c0, k1v)); s02 = wasm_f64x2_add(s02, wasm_f64x2_mul(c0, k2v));
                    s10 = wasm_f64x2_add(s10, wasm_f64x2_mul(c1, k0v)); s11 = wasm_f64x2_add(s11, wasm_f64x2_mul(c1, k1v)); s12 = wasm_f64x2_add(s12, wasm_f64x2_mul(c1, k2v));
                    s20 = wasm_f64x2_add(s20, wasm_f64x2_mul(c2, k0v)); s21 = wasm_f64x2_add(s21, wasm_f64x2_mul(c2, k1v)); s22 = wasm_f64x2_add(s22, wasm_f64x2_mul(c2, k2v));
                    s30 = wasm_f64x2_add(s30, wasm_f64x2_mul(c3, k0v)); s31 = wasm_f64x2_add(s31, wasm_f64x2_mul(c3, k1v)); s32 = wasm_f64x2_add(s32, wasm_f64x2_mul(c3, k2v));
                }
                wasm_v128_store(srow[0] + j, s00); wasm_v128_store(srow[0] + j + 2, s01); wasm_v128_store(srow[0] + j + 4, s02);
                wasm_v128_store(srow[1] + j, s10); wasm_v128_store(srow[1] + j + 2, s11); wasm_v128_store(srow[1] + j + 4, s12);
                wasm_v128_store(srow[2] + j, s20); wasm_v128_store(srow[2] + j + 2, s21); wasm_v128_store(srow[2] + j + 4, s22);
                wasm_v128_store(srow[3] + j, s30); wasm_v128_store(srow[3] + j + 2, s31); wasm_v128_store(srow[3] + j + 4, s32);
            }
            for (int t = 0; t < 4 && i0 + t < D; t++) {
                const int i = i0 + t;
                double *pi = Pm + i * MAXD;
                for (int j = i; j < D; j++) { double v = pi[j] - srow[t][j]; pi[j] = v; Pm[j * MAXD + i] = v; }
            }
        }
#else
        double srow[MAXD + 6];
        for (int i = 0; i < D; i++) {
            const int j0 = i - i % 6;
            for (int j = j0; j < D; j += 6) {
                v128_t s0 = wasm_f64x2_splat(0), s1 = s0, s2 = s0;
                for (int a = 0; a < k; a++) {
                    const v128_t c = wasm_f64x2_splat(HP[a * MAXD + i]);
                    const double *kt = Kt + a * MAXD + j;
                    s0 = wasm_f64x2_add(s0, wasm_f64x2_mul(c, wasm_v128_load(kt))); s1 = wasm_f64x2_add(s1, wasm_f64x2_mul(c, wasm_v128_load(kt + 2)));
                    s2 = wasm_f64x2_add(s2, wasm_f64x2_mul(c, wasm_v128_load(kt + 4)));
                }
                wasm_v128_store(srow + j, s0); wasm_v128_store(srow + j + 2, s1); wasm_v128_store(srow + j + 4, s2);
            }
            double *pi = Pm + i * MAXD;
            for (int j = i; j < D; j++) { double v = pi[j] - srow[j]; pi[j] = v; Pm[j * MAXD + i] = v; }
        }
#endif
    }
#else
    double col[MAXK];
    for (int j = 0; j < D; j++) { /* Kt = S^-1 HP (the transposed gain), column by column */
        for (int a = 0; a < k; a++) col[a] = HP[a * MAXD + j];
        chol_solve(Sm, k, col);
        for (int a = 0; a < k; a++) Kt[a * MAXD + j] = col[a];
    }
    double dx[MAXD];
    for (int j = 0; j < D; j++) {
        double s = 0;
        for (int a = 0; a < k; a++) s += Kt[a * MAXD + j] * r[a];
        dx[j] = s;
    }
    for (int i = 0; i < D; i++)
        for (int j = i; j < D; j++) {
            double s = 0;
            for (int a = 0; a < k; a++) s += HP[a * MAXD + i] * Kt[a * MAXD + j];
            double v = Pm[i * MAXD + j] - s;
            Pm[i * MAXD + j] = Pm[j * MAXD + i] = v;
        }
#endif
    inject(dx);
    return 1;
}

/* =====================================================================================================================
 * IMU: initialization, propagation, pseudo-measurements
 * ===================================================================================================================== */

static void set_block(int r, int c, const double *b, double scale) {
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) Pm[(r + i) * MAXD + c + j] = scale * b[3 * i + j];
}

/* frame 0: roll/pitch from the mean specific force (exact at hover; for a quadrotor in flight it points along the
   thrust axis, hence the tilt uncertainty), zero velocity with a wide prior, biases at their GP prior */
static void initialize(const double *imu, int count, double t) {
    double f[3] = {0, 0, 0};
    for (int r = 0; r < count; r++)
        for (int i = 0; i < 3; i++) f[i] += imu[7 * r + 1 + i] / count;
    align_to_z(f, R);
    memcpy(R0, R, sizeof R);
    memset(vel, 0, sizeof vel); memset(pos, 0, sizeof pos);
    memset(bg, 0, sizeof bg); memset(ba, 0, sizeof ba);
    memset(Pm, 0, sizeof Pm);
    D = CORE;
    double gm[3] = {0, 0, 0};
    for (int r = 0; r < count; r++)
        for (int i = 0; i < 3; i++) gm[i] += imu[7 * r + 4 + i] / count;
    moving = sqrt(gm[0] * gm[0] + gm[1] * gm[1] + gm[2] * gm[2]) > DET_GYRO || sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]) > DET_FORCE;
    if (GATE_STRESS || GATE_STRESS_OFF != 0.0) { /* test only: corrupt what the detector sees, not the filter */
        double fs[3] = {0, 0, 0}, gs[3] = {0, 0, 0}, bb[6];
        unsigned seed = (unsigned)(fabs(f[0] * 1e6)) * 2654435761u + (unsigned)(fabs(f[2] * 1e6));
        for (int i = 0; i < 6; i++) { seed = seed * 1664525u + 1013904223u; bb[i] = ((seed >> 8) / 8388608.0 - 1.0) * (i < 3 ? ACCEL_BIAS_MAX : GYRO_BIAS_MAX); }
        for (int r = 0; r < count; r++)
            for (int i = 0; i < 3; i++) {
                double n[2];
                for (int k = 0; k < 2; k++) { seed = seed * 1664525u + 1013904223u; double u1 = ((seed >> 8) + 1.0) / 16777217.0; seed = seed * 1664525u + 1013904223u; double u2 = (seed >> 8) / 16777216.0; n[k] = sqrt(-2 * log(u1)) * cos(6.283185307179586 * u2); }
                fs[i] += (imu[7 * r + 1 + i] + bb[i] + 1.7320508 * ACCEL_NOISE * n[0]) / count;
                gs[i] += (imu[7 * r + 4 + i] + bb[3 + i] + 1.7320508 * GYRO_NOISE * n[1]) / count;
            }
        moving = sqrt(gs[0] * gs[0] + gs[1] * gs[1] + gs[2] * gs[2]) > DET_GYRO || sqrt(fs[0] * fs[0] + fs[1] * fs[1] + fs[2] * fs[2]) + GATE_STRESS_OFF > DET_FORCE;
    }
    dbg_f = sqrt(f[0]*f[0]+f[1]*f[1]+f[2]*f[2]); dbg_g = sqrt(gm[0]*gm[0]+gm[1]*gm[1]+gm[2]*gm[2]); dbg_n = count;
    double ts = moving ? MOVE_TILT_STD : INIT_TILT_STD, vs = moving ? MOVE_VEL_STD : INIT_VELOCITY_STD;
    t_start = t;
    double tilt[9] = {ts * ts, 0, 0, 0, ts * ts, 0, 0, 0, 0}; /* yaw: gauge */
    set_block(TH, TH, tilt, 1); set_block(TH, TH0, tilt, 1); set_block(TH0, TH, tilt, 1); set_block(TH0, TH0, tilt, 1);
    set_block(V, V, I3, vs * vs);
    if (moving && PRIOR_MODE == 3) { /* heading-aware: mean along the camera axis, covariance in camera axes */
        double Rwc[9], mu[3] = {START_MEAN_X, START_MEAN_Y, START_MEAN_FWD}, sd[3] = {START_STD_X, START_STD_Y, START_STD_Z}, C[9];
        if (INV_GYV > 0) { /* gyro of the first window in camera axes */
            double wc[3], gb2[3] = {0, 0, 0};
            for (int rr2 = 0; rr2 < count; rr2++) for (int i = 0; i < 3; i++) gb2[i] += imu[7 * rr2 + 4 + i] / count;
            m3tvec(R_bc, gb2, wc);
            gyv_mx = INV_GYV * (wc[1] - wc[2]);
            if (gyv_mx > 1.0) gyv_mx = 1.0; if (gyv_mx < -1.0) gyv_mx = -1.0;
            mu[0] += gyv_mx; sd[0] = INV_GYV_SDX;
        }
        m3mul(R, R_bc, Rwc);
        m3vec(Rwc, mu, vel);
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++) {
                double a = 0;
                for (int k = 0; k < 3; k++) a += Rwc[3 * i + k] * sd[k] * sd[k] * Rwc[3 * j + k];
                C[3 * i + j] = a;
            }
        set_block(V, V, C, 1);
    }
    set_block(BG, BG, I3, INV_BGSD > 0 ? INV_BGSD * INV_BGSD : GYRO_BIAS_MAX * GYRO_BIAS_MAX / 3);
    set_block(BA, BA, I3, INV_BAZ > 0 ? INV_BAZ * INV_BAZ : ACCEL_BIAS_MAX * ACCEL_BIAS_MAX / 3);
    for (int i = 0; i < 3; i++) omega[i] = imu[7 * (count - 1) + 4 + i];
    last_t = t;
}

/* one IMU sample [t, ax, ay, az, gx, gy, gz]: nominal strapdown + covariance P <- F P F^T + Q.
 * F = I except   TH<-TH = dR^T, TH<-BG = -dt I, V<-TH = -dt R [a]x, V<-BA = -dt R, P<-V = dt I,
 * so F P F^T is a row pass then a column pass over the TH, V, P blocks only (clones are untouched by F). */
static void propagate(const double *row) {
    double dt = row[0] - last_t;
    if (dt <= 0) return;
    last_t = row[0];
    double w[3], a[3], wdt[3], dR[9], dRt[9], Ra[3], acc[3], sk[9], Rsk[9], Ms[9];
    for (int i = 0; i < 3; i++) { w[i] = row[4 + i] - bg[i]; a[i] = row[1 + i] - ba[i]; omega[i] = w[i]; wdt[i] = w[i] * dt; }
    exp_so3(wdt, dR);
    m3vec(R, a, Ra);
    acc[0] = Ra[0]; acc[1] = Ra[1]; acc[2] = Ra[2] - GRAVITY;
    for (int i = 0; i < 3; i++) for (int j = 0; j < 3; j++) dRt[3 * i + j] = dR[3 * j + i];
    skew(a, sk);
    m3mul(R, sk, Rsk);
    for (int i = 0; i < 9; i++) Ms[i] = -dt * Rsk[i];
    for (int pass = 0; pass < 2; pass++) { /* pass 0: rows (F P), pass 1: columns ((F P) F^T) */
        int rs = pass == 0 ? MAXD : 1, cs = pass == 0 ? 1 : MAXD;
        for (int c = 0; c < D; c++) {
            double th[3], v[3], p[3], gb[3], ab[3];
            for (int i = 0; i < 3; i++) {
                th[i] = Pm[(TH + i) * rs + c * cs]; v[i] = Pm[(V + i) * rs + c * cs]; p[i] = Pm[(P + i) * rs + c * cs];
                gb[i] = Pm[(BG + i) * rs + c * cs]; ab[i] = Pm[(BA + i) * rs + c * cs];
            }
            for (int i = 0; i < 3; i++) {
                Pm[(TH + i) * rs + c * cs] = dRt[3 * i] * th[0] + dRt[3 * i + 1] * th[1] + dRt[3 * i + 2] * th[2] - dt * gb[i];
                Pm[(V + i) * rs + c * cs] = v[i] + Ms[3 * i] * th[0] + Ms[3 * i + 1] * th[1] + Ms[3 * i + 2] * th[2]
                                             - dt * (R[3 * i] * ab[0] + R[3 * i + 1] * ab[1] + R[3 * i + 2] * ab[2]);
                Pm[(P + i) * rs + c * cs] = p[i] + dt * v[i];
            }
        }
    }
    /* Q: white noise on orientation and velocity; the GP bias kernels' random-walk increments */
    double q_th = (GYRO_NOISE * dt) * (GYRO_NOISE * dt), q_v = (ACCEL_NOISE * dt) * (ACCEL_NOISE * dt);
    double q_bg = GYRO_BIAS_WALK * GYRO_BIAS_WALK * dt, q_ba = ACCEL_BIAS_WALK * ACCEL_BIAS_WALK * dt;
    for (int i = 0; i < 3; i++) {
        Pm[(TH + i) * MAXD + TH + i] += q_th; Pm[(V + i) * MAXD + V + i] += q_v;
        Pm[(BG + i) * MAXD + BG + i] += q_bg; Pm[(BA + i) * MAXD + BA + i] += q_ba;
    }
    for (int i = 0; i < 3; i++) { pos[i] += vel[i] * dt + 0.5 * acc[i] * dt * dt; vel[i] += acc[i] * dt; }
    double Rn[9];
    m3mul(R, dR, Rn);
    memcpy(R, Rn, sizeof R);
}

static double Hs[3 * MAXD]; /* Jacobian rows of the small updates */

/* per frame: thrust model (frame-mean body x/y specific force = b_a,x/y), then the velocity prior */
/* ---- learned startup net (learned_c) ---- */
#define LC_SCALE 1.0
#ifndef LC_SPREAD
#define LC_SPREAD 3
#endif
/* ===================================================================================================================
 * Learned startup-velocity net (research/single_model/learned_c). Inference of train2.py's Net (nf=2, 64x48, width 1) in plain C.
 * Inputs: frame 0 and frame LC_K (=5), gyro-derotated into frame 0's orientation with the raw-gyro integral between them (own integration,
 * independent of the filter's biased state), per-frame normalisation, validity mask, coordinate channels; 19 IMU features
 * (window means of specific force/gyro at both frames, integral of R a dt, relative rotation vector, fx).
 * Output: body-frame velocity at frame 5 (head K) + per-axis log-variance. The forward pass can be spread over frames (LC_SPREAD).
 * Static memory only. Needs from the host file: fx, cx, cy, R_bc (camera -> body), update(), Hs, R, vel, MAXD, V.
 * =================================================================================================================== */
#ifndef LC_K
#define LC_K 5
#endif
#ifndef LC_SPREAD
#define LC_SPREAD 0          /* 0: whole net in frame LC_K; 1: stages over frames K..K+4; 2: over K..K+5 */
#endif
#ifndef LC_SCALE
#define LC_SCALE 1.0         /* multiplier on the predicted sigma */
#endif
#ifndef LC_FLOOR
#define LC_FLOOR 0.05        /* m/s, floor of the sigma used by the filter */
#endif
#ifndef LC_REPLACE
#define LC_REPLACE 1         /* 1: once the net has been applied, the heading prior's startup role ends */
#endif
#ifndef LC_SLOW_V
#define LC_SLOW_V 0.0       /* predicted speed below this: sigma floor LC_SLOW_FLOOR instead (hover-like starts) */
#endif
#ifndef LC_SLOW_FLOOR
#define LC_SLOW_FLOOR LC_FLOOR
#endif
#ifndef LC_SPD_K
#define LC_SPD_K 0.0         /* sigma *= 1 + K*predicted speed (calibration for fast starts) */
#endif
#ifndef LC_ENABLE
#define LC_ENABLE 1
#endif
#ifndef LC_EXTRA_SD
#define LC_EXTRA_SD 0.0      /* m/s added in quadrature (delay of the measurement) */
#endif
#define LC_W 128
#define LC_H 96
#define LC_PW 64
#define LC_PH 48
